{{ config(
            materialized='table',
                post_hook={
                    "sql": "ALTER SESSION SET TIMEZONE = \'Asia/Kolkata\'; CREATE OR REPLACE TABLE snitch_db.maplemonk.offline_walkins AS WITH Orders AS ( SELECT CAST(order_date AS DATE) AS order_dt, marketplace_mapped, BRANCH_CODE, COUNT(DISTINCT order_name) AS Orders, SUM(SUBORDER_QUANTITY) AS QTY FROM snitch_db.maplemonk.store_fact_items_offline WHERE DOC_PREFIX NOT IN (\'OMS\', \'QCOM\') AND order_date >= \'2025-07-01\' AND BRANCH_CODE NOT IN (\'45\',\'59\',\'32\',\'9\',\'35\',\'33\',\'76\',\'94\',\'46\',\'10\',\'60\',\'2\',\'8\',\'133\') AND ORDER_STATUS = \'Processed\' AND category != \'CARRY BAG\' GROUP BY 1,2,3 ), Stores AS ( SELECT a.STORE_CODE, COALESCE( b.branch_code, CASE WHEN a.STORE_CODE = \'Snitch-Kothapet-Hyderabad\' THEN 47 WHEN a.STORE_CODE = \'Snitch-Orion-Avenue-Mall-Bangalore\' THEN 56 WHEN a.STORE_CODE = \'Snitch-Kukatpally-Hyderabad\' THEN 20 WHEN a.STORE_CODE = \'Snitch-Sarath-City-Capital-Mall-Hyderabad\' THEN 16 WHEN a.STORE_CODE = \'Snitch-M5e-City-Mall-Bangalore\' THEN 62 WHEN a.STORE_CODE = \'Snitch-Lulu-Mall-Bangalore\' THEN 43 WHEN a.STORE_CODE = \'Snitch-Orion-Mall-Bangalore\' THEN 81 WHEN a.STORE_CODE = \'Snitch-Bhartiya-City-Mall-Bangalore\' THEN 41 WHEN a.STORE_CODE = \'Snitch-PMC-Bangalore\' THEN 55 WHEN a.STORE_CODE = \'Snitch-Waltair-Vizag\' THEN 29 WHEN a.STORE_CODE = \'Snitch-Mantri-Avenue-Koramangala-Bangalore\' THEN 19 WHEN a.STORE_CODE = \'Snitch-Jayanagar-Bangalore\' THEN 3 WHEN a.STORE_CODE = \'Snitch-New-Bel-Road-Bangalore\' THEN 14 WHEN a.STORE_CODE = \'Snitch-Banashankari-Bangalore\' THEN 57 WHEN a.STORE_CODE = \'Snitch-HSR-Layout-Bangalore\' THEN 13 WHEN a.STORE_CODE = \'Snitch-Elan-Miracle-Gurgaon\' THEN 67 WHEN a.STORE_CODE = \'Snitch-Palladium-Mall-Chennai\' THEN 84 WHEN a.STORE_CODE = \'Snitch-Gandhipuram-Rajahmundry\' THEN 50 WHEN a.STORE_CODE = \'Snitch-Gokul-Road-Hubli\' THEN 51 WHEN a.STORE_CODE = \'Snitch-City-Center-Mall-Mangalore\' THEN 27 WHEN a.STORE_CODE = \'Snitch-Vyapar-Vihar-Bilaspur\' THEN 87 WHEN a.STORE_CODE = \'Snitch-C-Road-Sardarpura-Jodhpur\' THEN 40 WHEN a.STORE_CODE = \'Snitch-Malviya-Nagar-Jaipur\' THEN 91 WHEN a.STORE_CODE = \'Snitch-Gumanpura-Kota\' THEN 86 WHEN a.STORE_CODE = \'Snitch-Mathura-road-Faridabad\' THEN 82 WHEN a.STORE_CODE = \'Snitch-Mittal-Mall-Ajmer\' THEN 64 WHEN a.STORE_CODE = \'SNITCH-COCO-LAJPAT-NAGAR\' THEN 49 WHEN a.STORE_CODE = \'SNITCH-COCO-MYSORE\' THEN 98 WHEN a.STORE_CODE = \'SNITCH-FOCO-VAISHALINAGAR\' THEN 39 WHEN a.STORE_CODE = \'SNITCH-COCO-SECTOR-29\' THEN 73 WHEN a.STORE_CODE = \'SNITCH-COFO-KARIMNAGAR\' THEN 79 WHEN a.STORE_CODE = \'SNITCH-COCO-GUWAHATI\' THEN 58 WHEN a.STORE_CODE = \'SNITCH-COCO-JANAKPURI\' THEN 90 WHEN a.STORE_CODE = \'SNITCH-COCO-SECTOR-50\' THEN 85 WHEN a.STORE_CODE = \'SNITCH-COCO-RAIPUR\' THEN 61 WHEN a.STORE_CODE = \'Snitch-Toli-Chowki-Hyderabad\' THEN 77 WHEN a.STORE_CODE = \'SNITCH-COFO-PALLADIUM-CHENNAI\' THEN 84 WHEN a.STORE_CODE = \'SNITCH-COCO-BANASHANKARI\' THEN 57 WHEN a.STORE_CODE = \'SNITCH-COCO-BHARTIYA-CITY\' THEN 41 WHEN a.STORE_CODE = \'SNITCH-COCO-PMC-WHITEFIELD-MALL\' THEN 55 WHEN a.STORE_CODE = \'SNITCH-COCO-M5-MALL\' THEN 62 WHEN a.STORE_CODE = \'SNITCH-FOCO-AJMER-MITTAL\' THEN 64 WHEN a.STORE_CODE = \'SNITCH-COFO-VIZAG\' THEN 29 WHEN a.STORE_CODE = \'SNITCH-COCO-FARIDABAD\' THEN 82 WHEN a.STORE_CODE = \'SNITCH-COCO-ELAN-MIRACLE\' THEN 67 WHEN a.STORE_CODE = \'SNITCH-COCO-ORION-MALL\' THEN 56 WHEN a.STORE_CODE = \'SNITCH-COFO-NIZAMABAD\' THEN 100 WHEN a.STORE_CODE = \'SNITCH-FOCO-C-ROAD-JODHPUR\' THEN 40 WHEN a.STORE_CODE = \'SNITCH-COCO-KORMANGLA\' THEN 19 WHEN a.STORE_CODE = \'SNITCH-COFO-HUBLI\' THEN 51 WHEN a.STORE_CODE = \'SNITCH-COCO-ORION-MALL-AVENUE\' THEN 56 WHEN a.STORE_CODE = \'SNITCH-COCO-LULU-MALL\' THEN 43 WHEN a.STORE_CODE = \'SNITCH-COCO-BEL-ROAD\' THEN 14 WHEN a.STORE_CODE = \'SNITCH-COCO-JAYANAGAR\' THEN 3 WHEN a.STORE_CODE = \'SNITCH-COCO-HSR-LAYOUT\' THEN 13 WHEN a.STORE_CODE = \'SNITCH-COFO-KOTHAPET\' THEN 47 WHEN a.STORE_CODE = \'SNITCH-FOCO-MALVIYA-NAGAR\' THEN 91 WHEN a.STORE_CODE = \'SNITCH-FOCO-KOTA\' THEN 86 WHEN a.STORE_CODE = \'SNITCH-COFO-KUKATPALLY\' THEN 20 WHEN a.STORE_CODE = \'SNITCH-COFO-CC-MANGALORE\' THEN 27 WHEN a.STORE_CODE = \'SNITCH-COFO-BILASPUR\' THEN 87 WHEN a.STORE_CODE = \'SNITCH-COFO-SARATH-CITY\' THEN 16 WHEN a.STORE_CODE = \'SNITCH-COFO-RAJAHMUNDRY\' THEN 50 WHEN a.STORE_CODE = \'SNITCH-FOCO-NIKOL\' THEN 99 WHEN a.STORE_CODE = \'SNITCH-COCO-M3M-MALL\' THEN 143 ELSE NULL END ) AS CODE, a.\"IN\" AS Walk_ins, CAST(COALESCE( TRY_TO_TIMESTAMP(a.DATETIME, \'MM/DD/YYYY HH24:MI:SS\'), TRY_TO_TIMESTAMP(a.DATETIME, \'MM-DD-YYYY HH24:MI:SS\') ) AS DATE) AS date_cast FROM snitch_db.maplemonk.snitch_db_get_store_count a LEFT JOIN snitch_db.maplemonk.delopt_mapping b ON UPPER(a.store_code) = UPPER(b.store_name) UNION ALL SELECT CASE store_id WHEN 16134 THEN \'SNITCH - COFO - CAPITAL MALL\' WHEN 15889 THEN \'SNITCH - COFO - NASHIK\' WHEN 16132 THEN \'SNITCH - COCO - GOLDUST PATIALA\' WHEN 16256 THEN \'SNITCH - COFO - SGS MALL\' WHEN 15875 THEN \'SNITCH - COCO - PARK STREET\' WHEN 15890 THEN \'SNITCH - COCO - PUNJABI BAGH\' WHEN 16133 THEN \'SNITCH - COFO - VIKRAMPURI\' WHEN 16473 THEN \'SNITCH - FOCO - LP SAVANI\' WHEN 16474 THEN \'SNITCH - COCO - RR NAGAR\' WHEN 16476 THEN \'SNITCH - FOCO - VAISHNODEVI\' WHEN 16475 THEN \'SNITCH - COCO - DIMAPUR\' END AS STORE_CODE, CASE store_id WHEN 16134 THEN 173 WHEN 15889 THEN 158 WHEN 16132 THEN 159 WHEN 16256 THEN 153 WHEN 15875 THEN 170 WHEN 15890 THEN 161 WHEN 16133 THEN 174 WHEN 16473 THEN 168 WHEN 16474 THEN 160 WHEN 16476 THEN 165 WHEN 16475 THEN 177 END AS CODE, SUM(passengerflow) AS Walk_ins, TO_DATE(TRY_TO_TIMESTAMP(time, \'YYYY-MM-DD HH24:MI:SS\')) AS date_cast FROM ( SELECT * FROM snitch_db.maplemonk.snitch_get_many_shops_passenger_indicator_data QUALIFY ROW_NUMBER() OVER (PARTITION BY store_id, time ORDER BY time) = 1 ) WHERE HOUR(TRY_TO_TIMESTAMP(time, \'YYYY-MM-DD HH24:MI:SS\')) BETWEEN 10 AND 22 AND TO_DATE(TRY_TO_TIMESTAMP(time, \'YYYY-MM-DD HH24:MI:SS\')) < CURRENT_DATE() AND store_id IN (15889, 16132, 16256, 15875, 15890, 16133) GROUP BY 1, 2, 4 ), metricss AS ( SELECT * FROM snitch_db.maplemonk.Offline_Detailed_Summary_V2 ) SELECT s.STORE_CODE, s.CODE, s.date_cast AS store_date, CURRENT_DATE AS Current_date_mapped, s.Walk_ins, o.order_dt AS order_date, o.marketplace_mapped, o.Orders, o.QTY, B.TODAY_SALES, B.TARGET, B.MTD_SALES, B.MTD, B.BILLS, B.MULTIES, B.QTY AS QTYSS, B.ATV, B.UPT, B.ASP, B.AM, B.STATE FROM Stores s LEFT JOIN Orders o ON s.CODE = o.BRANCH_CODE AND s.date_cast = o.order_dt LEFT JOIN metricss B ON s.CODE = B.BRANCH_CODE AND s.date_cast = B.DATE WHERE s.CODE IS NOT NULL and o.order_dt is not null;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
